import * as THREE from 'three'
import data from '../data/die-holes.json'

/**
 * The noodler die plate's through-hole pattern, measured offline.
 *
 * The JSON is generated by scripts/extract-die-holes.mjs and holds coordinates
 * in the PLATE'S OWN local space. Resolving them here, against the plate's live
 * transform, is what makes the data survive a re-export that changes the
 * model's scale, orientation or node tree - which has already happened once.
 */
export interface DieHoleField {
  /** Scene-relative hole centres on the downstream face, 3 floats per hole. */
  positions: Float32Array
  count: number
  /** Hole radius in scene units. */
  radius: number
  /** Scene-relative z of the face the noodles leave from. */
  faceZ: number
}

// `object`'s transform as if `scene` were sitting at the identity transform.
// Everything in this viewer is a child of the loaded scene and works in this
// space - see the same helper in GateHinge, MixerFill and hopperSurface. Using
// matrixWorld here instead would double-apply the model's own position offset,
// which App.tsx sets to roughly (0.77, 0.01, 0) to stand the machine on the
// ground: the whole pattern would land beside the machine rather than in it.
function getSceneRelativeMatrix(object: THREE.Object3D, scene: THREE.Object3D, target: THREE.Matrix4) {
  scene.updateWorldMatrix(true, false)
  object.updateWorldMatrix(true, false)
  return target.copy(scene.matrixWorld).invert().multiply(object.matrixWorld)
}

/**
 * Places the measured hole pattern into the scene.
 *
 * Returns null when the plate cannot be found or no longer matches the data it
 * was measured from. Null means "draw nothing": noodles in the wrong place are
 * worse than no noodles, because a plant viewer showing material somewhere it
 * is not is actively misleading, where a missing curtain is merely incomplete.
 */
export function resolveDieHoles(scene: THREE.Object3D): DieHoleField | null {
  const die = scene.getObjectByName(data.mesh.name) as THREE.Mesh | undefined
  if (!die || !die.isMesh || !die.geometry) {
    console.error(`[dieHoles] mesh "${data.mesh.name}" not found - was the model re-exported?`)
    return null
  }

  const vertexCount = die.geometry.attributes.position.count
  if (vertexCount !== data.mesh.vertexCount) {
    console.error(
      `[dieHoles] "${data.mesh.name}" has ${vertexCount} vertices, expected ${data.mesh.vertexCount}. ` +
        'The plate changed; re-run `npm run extract:die-holes`.',
    )
    return null
  }

  const matrix = getSceneRelativeMatrix(die, scene, new THREE.Matrix4())
  const position = new THREE.Vector3()
  const quaternion = new THREE.Quaternion()
  const scale = new THREE.Vector3()
  matrix.decompose(position, quaternion, scale)

  // A single radius scalar is only meaningful under a uniform scale.
  if (Math.max(scale.x, scale.y, scale.z) / Math.min(scale.x, scale.y, scale.z) > 1.001) {
    console.error(`[dieHoles] die scale is non-uniform (${scale.toArray().join(', ')})`)
    return null
  }

  const positions = new Float32Array(data.holes.length * 3)
  const point = new THREE.Vector3()
  let faceZ = 0
  for (let i = 0; i < data.holes.length; i++) {
    const [u, v] = data.holes[i]
    point.set(u, v, data.downstreamFaceLocalZ).applyMatrix4(matrix)
    positions[i * 3] = point.x
    positions[i * 3 + 1] = point.y
    positions[i * 3 + 2] = point.z
    // Every hole is on the same face plane by construction, so any of them
    // carries its depth.
    if (i === 0) faceZ = point.z
  }

  return {
    positions,
    count: data.holes.length,
    radius: data.holeRadiusLocal * scale.x,
    faceZ,
  }
}

/**
 * Scene-relative top surface of whatever the strands land on.
 *
 * Probed from the mesh rather than taken from the JSON: the extract records the
 * belt's height only as provenance, and the model is what actually decides
 * where a noodle stops.
 */
export function resolveLandingY(scene: THREE.Object3D): number | null {
  return resolveLandingBounds(scene)?.max.y ?? null
}

/**
 * Scene-relative extent of one named mesh.
 *
 * Anything that positions product against a machine part measures the part
 * rather than carrying a copy of its coordinates. Hard-coded numbers here would
 * leave noodles vanishing in mid-air, or sliding through a roll, after any
 * re-export - and the model has already been re-exported once.
 */
export function resolveMeshBounds(scene: THREE.Object3D, meshName: string): THREE.Box3 | null {
  const object = scene.getObjectByName(meshName) as THREE.Mesh | undefined
  if (!object || !object.geometry) {
    console.error(`[dieHoles] mesh "${meshName}" not found`)
    return null
  }
  object.geometry.computeBoundingBox()
  return object.geometry.boundingBox!.clone().applyMatrix4(getSceneRelativeMatrix(object, scene, new THREE.Matrix4()))
}

export type GuidePlane = {
  /** Unit normal, pointing up out of the surface. */
  normal: THREE.Vector3
  /** Plane constant: a point p is on the plane where normal.dot(p) === constant. */
  constant: number
  /** Extent of the faces that make up this plane - product only contacts inside it. */
  bounds: THREE.Box3
}

/** Shallowest face still treated as something product runs down rather than a wall. */
const GUIDE_MIN_NORMAL_Y = 0.15
/** Planes smaller than this share of the largest are trim, not carrying surface. */
const GUIDE_MIN_AREA_SHARE = 0.05

/**
 * The up-facing surfaces of a chute, deflector or funnel, as planes product can
 * slide on.
 *
 * A SET of planes rather than one, because the guides on this line are not all
 * simple ramps. The upper plate is a flat slab, but the lower guide is a
 * V-funnel: two opposed walls at 50.9 degrees that converge on a throat. Fitting
 * either a bounding box or a single plane to that gives a surface which is not
 * there - a box says nothing about slope at all, and one plane through a V is a
 * lid across its mouth.
 *
 * Coplanar triangles are merged, so a 752-triangle funnel collapses to the three
 * walls it actually has and contact stays a handful of tests per piece rather
 * than hundreds. Faces are grouped by normal AND by plane constant, so two
 * parallel surfaces at different heights stay separate.
 *
 * Downhill is not returned: it is just gravity projected onto the plane, which
 * the caller gets for free by cancelling the into-surface component of velocity.
 * Deriving the slide that way keeps it real rather than scripted.
 */
export function resolveGuidePlanes(scene: THREE.Object3D, meshName: string): GuidePlane[] {
  const object = scene.getObjectByName(meshName) as THREE.Mesh | undefined
  if (!object || !object.geometry) {
    console.error(`[dieHoles] guide mesh "${meshName}" not found`)
    return []
  }

  const matrix = getSceneRelativeMatrix(object, scene, new THREE.Matrix4())
  const position = object.geometry.attributes.position
  const index = object.geometry.index
  const count = index ? index.count : position.count
  const read = (i: number, out: THREE.Vector3) =>
    out.fromBufferAttribute(position, index ? index.getX(i) : i).applyMatrix4(matrix)

  const a = new THREE.Vector3()
  const b = new THREE.Vector3()
  const c = new THREE.Vector3()
  const ab = new THREE.Vector3()
  const ac = new THREE.Vector3()
  const cross = new THREE.Vector3()

  const groups = new Map<string, { normal: THREE.Vector3; constant: number; bounds: THREE.Box3; area: number }>()

  for (let i = 0; i < count; i += 3) {
    read(i, a)
    read(i + 1, b)
    read(i + 2, c)
    cross.crossVectors(ab.subVectors(b, a), ac.subVectors(c, a))
    const doubleArea = cross.length()
    if (doubleArea === 0) continue
    cross.divideScalar(doubleArea)
    if (cross.y < GUIDE_MIN_NORMAL_Y) continue

    const constant = cross.dot(a)
    // Rounded so that triangles meant to be coplanar land in one bucket despite
    // 16-bit quantised positions, but not so coarse that distinct walls merge.
    const key = `${cross.x.toFixed(2)},${cross.y.toFixed(2)},${cross.z.toFixed(2)}|${constant.toFixed(3)}`
    let group = groups.get(key)
    if (!group) {
      group = { normal: cross.clone(), constant, bounds: new THREE.Box3().makeEmpty(), area: 0 }
      groups.set(key, group)
    }
    group.area += doubleArea / 2
    group.bounds.expandByPoint(a).expandByPoint(b).expandByPoint(c)
  }

  const found = [...groups.values()].sort((p, q) => q.area - p.area)
  if (found.length === 0) {
    console.error(`[dieHoles] guide mesh "${meshName}" has no upward-facing surface`)
    return []
  }

  const cutoff = found[0].area * GUIDE_MIN_AREA_SHARE
  return found
    .filter((group) => group.area >= cutoff)
    .map(({ normal, constant, bounds }) => ({ normal, constant, bounds }))
}

/**
 * Scene-relative extent of the belt the strands land on.
 *
 * The noodles ride it until they run off the end, so where that end is has to
 * come from the belt itself.
 */
export function resolveLandingBounds(scene: THREE.Object3D): THREE.Box3 | null {
  return resolveMeshBounds(scene, data.landing.mesh)
}
